def variable(f, y, starts, lower, upper):
    from scipy.optimize import least_squares

    def calc(k):
        A = f(k)
        return A @ np.linalg.lstsq(A, y, rcond=None)[0] - y
    opts = []
    for start in starts:
        r = least_squares(calc, start, bounds=(lower, upper), max_nfev=120, gtol=1e-11)
        opts.append((np.mean(r.fun ** 2) ** 0.5, r.x, np.max(abs(r.fun))))
    return min(opts, key=lambda a: a[0])

def _project(study, S, y):
    z = np.asarray(study['Z_nuisance'])
    gram = z.T @ z + study['nuisance_ridge'] * np.eye(z.shape[1])
    values = np.column_stack((S, y))
    values -= z @ np.linalg.solve(gram, z.T @ values)
    return (values[:, :-1], values[:, -1])
